import csv
import io


def parse_csv(raw_csv: str):
    width = 7
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    with io.StringIO(raw_csv, newline="") as source:
        records = list(csv.reader(
            source, delimiter=",", quotechar='"', doublequote=True
        ))

    # The first record with the expected width is the single header row.
    # Shorter records before it may be preamble text.
    header_index = next(
        (index for index, record in enumerate(records) if len(record) == width),
        None,
    )
    if header_index is None:
        header_index = next(
            (index for index, record in enumerate(records) if record),
            None,
        )
    if header_index is None:
        return {"columns": [], "rows": []}

    def normalize(record):
        if len(record) > width:
            # Keep overflow text in the last column rather than dropping it.
            return record[:width - 1] + [",".join(record[width - 1:])]
        return record + [""] * (width - len(record))

    return {
        "columns": normalize(records[header_index]),
        "rows": [normalize(record) for record in records[header_index + 1:]],
    }
